private func testFunc32(a: [Float], b: [Float]) -> Float {
    let n = withoutDerivative(at: min(a.count, b.count))
    var sum: Float = 0
    for i in 0 ..< n {
        let a32 = a[i]
        let b32 = b[i]
        let t0 = abs(b32)
        sum += t0
    }
    return sum
}

